 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** Picks the language for an Accept-Language header (q-values and region tags honored), else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (Array.isArray(header)) header = header.join(",");
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const ranges = [];
+  header.split(",").forEach((part, index) => {
+    const [tag, ...attrs] = part.trim().split(";");
+    const range = tag.trim().toLowerCase();
+    if (!range) return;
+    let q = 1;
+    for (const a of attrs) {
+      const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(a);
+      if (m) q = Number(m[1]);
+    }
+    if (!(q > 0 && q <= 1)) return;
+    const primary = range === "*" ? fallback : range.split("-")[0];
+    if (LANGUAGES.includes(primary)) ranges.push({ lang: primary, q, index });
+  });
+  ranges.sort((a, b) => b.q - a.q || a.index - b.index);
+  return ranges.length ? ranges[0].lang : fallback;
+}
